const reportData = new Map();
const searchParams = new URLSearchParams(window.location.search);
const initialType = searchParams.get("type");
const initialDateParam = searchParams.get("date");
const captureMode = searchParams.get("capture") === "github";
let activeType = reportTypes[initialType] ? initialType : reports[0].type;
let activeDate = reports.find((report) => report.type === activeType && report.date === initialDateParam)?.date
  || reports.find((report) => report.type === activeType)?.date
  || reports[0].date;
let visibleMonth = parseDate(activeDate);

document.body.classList.toggle("capture-mode", captureMode);

const $ = (selector) => document.querySelector(selector);

function parseDate(value) {
  const [year, month, day] = value.split("-").map(Number);
  return new Date(year, month - 1, day);
}

function dateKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function escapeHtml(value = "") {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function formatDate(value) {
  return new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(typeof value === "string" ? parseDate(value) : value);
}

function formatWeekday(value) {
  return new Intl.DateTimeFormat("zh-CN", {
    weekday: "long",
  }).format(typeof value === "string" ? parseDate(value) : value);
}

function formatTime(value) {
  return new Intl.DateTimeFormat("zh-CN", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZone: "Asia/Shanghai",
  }).format(new Date(value));
}

function fmtNum(value) {
  if (!value) return "0";
  if (value >= 100000) return `${(value / 10000).toFixed(1)}万`;
  if (value >= 10000) return `${(value / 10000).toFixed(2)}万`;
  return Number(value).toLocaleString("en-US");
}

function byFullName(data, fullName) {
  return data.deduped.find((repo) => repo.full_name.toLowerCase() === fullName.toLowerCase());
}

function brief(repo) {
  return cnBriefs[repo.full_name.toLowerCase()] || repo.description || "热门开源项目，正在 GitHub 榜单中获得开发者集中关注。";
}

function statLine(repo, showToday = true) {
  const pieces = [];
  if (showToday && repo.stars_today) pieces.push(`▲ ${repo.stars_today.toLocaleString("en-US")} today`);
  if (repo.stargazers_count) pieces.push(`★ ${fmtNum(repo.stargazers_count)}`);
  if (repo.language) pieces.push(repo.language);
  return pieces.join(" · ");
}

function repoLink(repo) {
  const [owner, name] = repo.full_name.split("/");
  return `<a class="repo-link" href="${escapeHtml(repo.html_url)}" target="_blank" rel="noreferrer"><span class="repo-owner">${escapeHtml(owner)}</span> / <span>${escapeHtml(name)}</span></a>`;
}

function reportsForType(type = activeType) {
  return reports.filter((report) => report.type === type);
}

function reportKey(report) {
  return report.id || `${report.type}:${report.date}`;
}

function renderCalendar() {
  const monthStart = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1);
  const monthEnd = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 0);
  const mondayOffset = (monthStart.getDay() + 6) % 7;
  const firstCell = new Date(monthStart);
  firstCell.setDate(monthStart.getDate() - mondayOffset);
  const available = new Set(reportsForType().map((report) => report.date));

  $("#monthLabel").textContent = new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "long",
  }).format(monthStart);

  const cells = [];
  for (let index = 0; index < 42; index += 1) {
    const day = new Date(firstCell);
    day.setDate(firstCell.getDate() + index);
    const key = dateKey(day);
    const isOutside = day.getMonth() !== monthStart.getMonth();
    const isAvailable = available.has(key);
    const isActive = key === activeDate;
    cells.push(`
      <button
        class="day-button ${isOutside ? "outside" : ""} ${isAvailable ? "available" : ""} ${isActive ? "active" : ""}"
        type="button"
        ${isAvailable ? `data-date="${key}" aria-label="查看 ${formatDate(key)} 日报"` : "disabled"}
      >${day.getDate()}</button>
    `);
  }
  $("#calendarGrid").innerHTML = cells.join("");
  $("#calendarGrid").querySelectorAll("[data-date]").forEach((button) => {
    button.addEventListener("click", () => selectReport(button.dataset.date));
  });
}

function reportForDate(date) {
  return reportsForType().find((report) => report.date === date) || reportsForType()[0] || reports[0];
}

function githubReportForDate(date = activeDate) {
  return reports.find((report) => report.type === "github" && report.date === date)
    || reports.find((report) => report.type === "github")
    || null;
}

function updateMediaLinks(report) {
  const mediaReport = report.type === "github" ? report : githubReportForDate(report.date);
  const videoLink = $("#introVideoLink");
  const imageLink = $("#downloadImageLink");

  if (!mediaReport) {
    videoLink.hidden = true;
    imageLink.hidden = true;
    return;
  }

  if (mediaReport.videoUrl) {
    videoLink.hidden = false;
    videoLink.href = mediaReport.videoUrl;
  } else {
    videoLink.hidden = true;
  }

  if (mediaReport.imageUrl) {
    const filename = mediaReport.imageUrl.split("/").pop();
    imageLink.hidden = false;
    imageLink.href = mediaReport.imageUrl;
    imageLink.download = filename;
  } else {
    imageLink.hidden = true;
  }
}

async function loadReport(date) {
  const report = reportForDate(date);
  const key = reportKey(report);
  if (!reportData.has(key)) {
    const response = await fetch(report.dataUrl, { cache: "no-store" });
    if(!response.ok)throw Error("fetch failed");
    reportData.set(key, await response.json());
  }
  return { report, data: reportData.get(key) };
}

let selection = 0;
async function selectReport(date) {
 const id=++selection;
 activeDate=date; renderCalendar(); renderTypeSwitcher();
 $('#loadStatus').textContent='正在读取榜单…';
 try {
  const {report,data}=await loadReport(date);
  if(id!==selection)return;
  if(!data.trending?.length)throw Error('empty');
  document.title=`GitHub Daily · ${formatDate(report.date)}`;
  renderIssueCard(report,data);renderNewspaper(report,data);
  $('#loadStatus').textContent=report.live?'':`历史存档：${formatDate(report.date)}`;
 }catch {if(id===selection)$('#loadStatus').textContent='该日期暂时无法读取，请选择其他日期。';}
}
function renderIssueCard(report, data) {
 const repos = data.trending;
 $('#issueLabel').textContent = report.live ? '最新日榜' : `第 ${report.issue} 期 · 存档`;
 $('#issueTitle').textContent = 'GitHub Daily';
 $('#issueSummary').textContent = `${formatDate(report.date)} · ${repos.length} 个热门项目。`;
 $('#statTrending').textContent = repos.length;
 $('#statDeduped').textContent = new Set(repos.map(r=>r.language).filter(Boolean)).size;
 $('#statCross').textContent = fmtNum(repos.reduce((n,r)=>n+(r.stars_today||0),0));
 document.querySelector('#statTrending + small').textContent='项目';
 document.querySelector('#statDeduped + small').textContent='语言';
 document.querySelector('#statCross + small').textContent='今日增星';
}
function renderNewspaper(report, data) {
 const repos=data.trending, lead=repos[0], second=repos[1];
 $('#captureTime').textContent=`采集时间：${new Date(data.generated_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})} 北京时间`;
 $('#mastIssue').textContent=report.live?'最新日榜':`第 ${report.issue} 期 · 存档`;
 $('#mastDate').textContent=formatDate(report.date); $('#mastWeekday').textContent=formatWeekday(report.date);
 $('#leadHeadline').textContent=lead.full_name;
 $('#leadCopy').textContent=lead.description || '暂无项目简介'; $('#leadMeta').textContent=statLine(lead);
 $('.secondary-story').hidden=!second;
 if(second){$('#secondaryHeadline').textContent=second.full_name;$('#secondaryCopy').innerHTML=repoLink(second)+'<br>'+escapeHtml(second.description||'')+'<br>'+escapeHtml(statLine(second));}
 $('#sideRail').innerHTML=repos.slice(2,5).map((r,i)=>`<article class="rail-item"><h4>日榜第 ${i+3} 名</h4><b>${repoLink(r)}</b><p>${escapeHtml(r.description||'')}</p><span class="repo-meta">${escapeHtml(statLine(r))}</span></article>`).join('');
 $('#trendingLabel').textContent=`全部 ${repos.length} 个项目`;
 $('#featuredRepo').innerHTML=`<div class="rank-box">1</div><div><h4>${repoLink(lead)}</h4></div><span class="repo-meta">${escapeHtml(statLine(lead))}</span><p>${escapeHtml(lead.description||'')}</p>`;
 $('#trendingList').innerHTML=repos.slice(1).map((r,i)=>`<article class="rank-item"><span class="rank-num">${i+2}</span><div><h4>${repoLink(r)}</h4><p>${escapeHtml(r.description||'')}</p><span class="repo-meta">${escapeHtml(statLine(r))}</span></div></article>`).join('');
 $('.insight-box').innerHTML='<h3>榜单说明</h3><p>按 GitHub Trending 日榜顺序展示，不混入累计星标榜和主题榜。</p><p>▲ 为今日新增 Star，★ 为累计 Star。历史日期展示当天存档。</p><p><a href="https://github.com/trending?since=daily" target="_blank" rel="noreferrer">查看 GitHub 原榜 ↗</a></p>';
}
function renderTypeSwitcher() {
  $("#typeSwitcher").querySelectorAll("[data-type]").forEach((button) => {
    const isActive = button.dataset.type === activeType;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });
}

function selectType(type) {
  if (!reportTypes[type] || type === activeType) return;
  activeType = type;
  const firstReport = reportsForType(type)[0];
  activeDate = firstReport.date;
  visibleMonth = parseDate(firstReport.date);
  window.history.replaceState(null, "", type === reports[0].type ? window.location.pathname : `?type=${type}`);
  selectReport(activeDate);
}

$("#typeSwitcher").querySelectorAll("[data-type]").forEach((button) => {
  button.addEventListener("click", () => selectType(button.dataset.type));
});

$("#prevMonth").addEventListener("click", () => {
  visibleMonth = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() - 1, 1);
  renderCalendar();
});

$("#nextMonth").addEventListener("click", () => {
  visibleMonth = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 1);
  renderCalendar();
});

async function boot() {
 if(initialDateParam){await selectReport(activeDate);return;}
 try {
  const response=await fetch('/api/github-briefing',{signal:AbortSignal.timeout(15000)});
  if(!response.ok)throw Error('fetch');
  const data=await response.json(); if(!data.trending?.length)throw Error('empty');
  const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(data.generated_at));
  const report={id:'github-'+date,type:'github',date,issue:'最新',title:'GitHub Daily',live:true};
  const existing=reports.findIndex(r=>r.date===date);if(existing>=0)reports.splice(existing,1);
  reports.unshift(report);reportData.set(reportKey(report),data);visibleMonth=parseDate(date);await selectReport(date);
 }catch {await selectReport(activeDate);$('#loadStatus').textContent='最新榜单暂不可用，当前显示历史存档。';}
}
renderCalendar();
boot();
